/* ---------- Utilities ---------- */
const U = (() => {
  const clone = (obj) => (typeof structuredClone === "function" ? structuredClone(obj) : JSON.parse(JSON.stringify(obj)));
  const escape = (v) => String(v || "")
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
    .replace(/\"/g, "&quot;").replace(/'/g, "&#039;");
  const todayISO = () => {
    const d = new Date();
    const mm = String(d.getMonth() + 1).padStart(2, '0');
    const dd = String(d.getDate()).padStart(2, '0');
    return `${d.getFullYear()}-${mm}-${dd}`;
  };
  const nowUS = () => {
    const d = new Date();
    const mm = String(d.getMonth() + 1).padStart(2, '0');
    const dd = String(d.getDate()).padStart(2, '0');
    const yy = String(d.getFullYear()).slice(-2);
    return `${mm}/${dd}/${yy}`;
  };
  const safeFileName = (parts, fallback) => {
    const s = (parts || []).filter(Boolean).join("_").replace(/[^a-zA-Z0-9 _-]/g, "").trim();
    return s || fallback || "Emjac_Document";
  };
  const byId = (id) => document.getElementById(id);
  const safeJSON = (raw, fb = null) => { try { return JSON.parse(raw); } catch { return fb; } };
  return { clone, escape, esc: escape, todayISO, nowUS, safeFileName, byId, safeJSON };
})();

/* ---------- Metal Inventory Part Database (embedded) ---------- */
const METAL_INV_XLSX_B64 = "";
/* NOTE: Uses SheetJS (XLSX) loaded from CDN in index.html */

/* ---------- Storage ---------- */
const S = (() => {
  const LS_KEY = "emjac_user_guide_app_v8";
  const LS_ADMIN = "emjac_is_admin_v1";

  const LS_HC_CFG = "emjac_harmonic_checklist_cfg_v2";
  const LS_HC_JOB_PREFIX = "emjac_harmonic_checklist_job_v2:"; // + jobKey|templateId

  const getJSON = (k, fb = null) => {
    const raw = localStorage.getItem(k);
    if (!raw) return fb;
    try { return JSON.parse(raw); } catch { return fb; }
  };
  const setJSON = (k, v) => localStorage.setItem(k, JSON.stringify(v));

  const isAdmin = () => sessionStorage.getItem(LS_ADMIN) === "1";
  const setAdmin = (v) => sessionStorage.setItem(LS_ADMIN, v ? "1" : "0");

  const baseJobKey = ({ salesOrder, itemNumber, jobName }) => {
    const so = (salesOrder || "").trim();
    const item = (itemNumber || "").trim();
    const job = (jobName || "").trim();
    const base = [so, item].filter(Boolean).join("|") || job || "UNNAMED";
    return base.replace(/\s+/g, " ").trim();
  };

  const fullKey = (baseKey, templateId) => `${baseKey}|${templateId}`;

  const loadJob = (baseKey, templateId) => getJSON(LS_HC_JOB_PREFIX + fullKey(baseKey, templateId), null);
  const saveJob = (baseKey, templateId, v) => setJSON(LS_HC_JOB_PREFIX + fullKey(baseKey, templateId), v);
  const clearJob = (baseKey, templateId) => localStorage.removeItem(LS_HC_JOB_PREFIX + fullKey(baseKey, templateId));

  // Shared carry-over store for items that should persist across templates for the same job
  const LS_HC_SHARED_PREFIX = "emjac_harmonic_checklist_shared_v1:"; // + baseKey|itemId
  const sharedKey = (baseKey, itemId) => `${baseKey}|${itemId}`;
  const loadShared = (baseKey, itemId) => getJSON(LS_HC_SHARED_PREFIX + sharedKey(baseKey, itemId), null);
  const saveShared = (baseKey, itemId, v) => setJSON(LS_HC_SHARED_PREFIX + sharedKey(baseKey, itemId), v);


  return { LS_KEY, LS_ADMIN, LS_HC_CFG, LS_HC_JOB_PREFIX, getJSON, setJSON, isAdmin, setAdmin, baseJobKey, fullKey, loadJob, saveJob, clearJob, loadShared, saveShared };

  /* ---------- Media (Photos via IndexedDB — offline-safe) ---------- */
  /*
    Shared photo storage for:
    - Quality Control (per section)
    - Harmonic Checklists (per section)
    - Labels (per label)
  
    We store Blobs in IndexedDB and only keep photo ids in localStorage state.
  */
  const Media = (() => {
    const DB_NAME = "emjac_media_db_v1";
    const DB_VERSION = 1;
    const STORE = "photos";

    const openDb = () => new Promise((resolve, reject) => {
      const req = indexedDB.open(DB_NAME, DB_VERSION);
      req.onupgradeneeded = () => {
        const db = req.result;
        if (!db.objectStoreNames.contains(STORE)) {
          const os = db.createObjectStore(STORE, { keyPath: "id" });
          // Context index enables fast listing per module/job/template/item/section
          os.createIndex("byContext", ["ctx", "jobKey", "templateId", "itemIndex", "section"], { unique: false });
          os.createIndex("byCtxJob", ["ctx", "jobKey"], { unique: false });
        }
      };
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => reject(req.error);
    });

    const txStore = async (mode = "readonly") => {
      const db = await openDb();
      const tx = db.transaction(STORE, mode);
      return { db, tx, store: tx.objectStore(STORE) };
    };

    const newId = () => (crypto && crypto.randomUUID) ? crypto.randomUUID() : ("p_" + Date.now() + "_" + Math.floor(Math.random() * 1e9));

    const blobToDataUrl = (blob) => new Promise((resolve) => {
      const fr = new FileReader();
      fr.onload = () => resolve(fr.result);
      fr.onerror = () => resolve("");
      fr.readAsDataURL(blob);
    });

    // Resize/compress image before storing
    const fileToJpegBlob = async (file, maxW = 1280, quality = 0.72) => {
      const bmp = await createImageBitmap(file);
      const scale = Math.min(1, maxW / (bmp.width || maxW));
      const w = Math.max(1, Math.round(bmp.width * scale));
      const h = Math.max(1, Math.round(bmp.height * scale));

      const canvas = document.createElement("canvas");
      canvas.width = w; canvas.height = h;
      const ctx2d = canvas.getContext("2d");
      ctx2d.drawImage(bmp, 0, 0, w, h);

      return await new Promise((resolve) => {
        canvas.toBlob((blob) => resolve(blob || file), "image/jpeg", quality);
      });
    };

    const put = async ({ ctx, jobKey, templateId, itemIndex, section, file }) => {
      const blob = await fileToJpegBlob(file);
      const rec = {
        id: newId(),
        ctx: ctx || "qc",
        jobKey: jobKey || "",
        templateId: templateId || "",
        itemIndex: Number.isFinite(itemIndex) ? itemIndex : 0,
        section: section || "",
        createdAt: new Date().toISOString(),
        blob
      };

      const { db, tx, store } = await txStore("readwrite");
      await new Promise((res, rej) => { const r = store.put(rec); r.onsuccess = () => res(); r.onerror = () => rej(r.error); });
      await new Promise((res) => { tx.oncomplete = () => res(); tx.onerror = () => res(); tx.onabort = () => res(); });
      db.close();
      return rec.id;
    };

    const get = async (photoId) => {
      const { db, store } = await txStore("readonly");
      const rec = await new Promise((res) => { const r = store.get(photoId); r.onsuccess = () => res(r.result || null); r.onerror = () => res(null); });
      db.close();
      return rec;
    };

    const del = async (photoId) => {
      const { db, tx, store } = await txStore("readwrite");
      await new Promise((res) => { const r = store.delete(photoId); r.onsuccess = () => res(); r.onerror = () => res(); });
      await new Promise((res) => { tx.oncomplete = () => res(); tx.onerror = () => res(); tx.onabort = () => res(); });
      db.close();
    };

    const list = async ({ ctx, jobKey, templateId, itemIndex, section }) => {
      const { db, store } = await txStore("readonly");
      const idx = store.index("byContext");
      const key = [ctx || "qc", jobKey || "", templateId || "", Number.isFinite(itemIndex) ? itemIndex : 0, section || ""];
      const recs = await new Promise((res) => {
        const out = [];
        const r = idx.openCursor(IDBKeyRange.only(key));
        r.onsuccess = () => {
          const cur = r.result;
          if (!cur) { res(out); return; }
          out.push(cur.value);
          cur.continue();
        };
        r.onerror = () => res(out);
      });
      db.close();
      recs.sort((a, b) => (a.createdAt < b.createdAt ? 1 : -1));
      return recs;
    };

    return { put, get, del, list, blobToDataUrl };
  })();
})();


