/* =========================
   Metal Inventory (Voice Session + Excel Export)
   - Location (voice) + Part# (voice lookup) + Stack Height (in) + Paper/No Paper
   - Paper between every sheet adds 0.004" per sheet layer
   - Qty = floor(stackHeight / (sheetThick + paperThick))
   - Session-based: multiple entries, pause/exit, one supervisor signature at completion
   ========================= */
const MetalInventory = (() => {
  const LS_ACTIVE = "emjac_mi_active_session_v1";

  // Session state (Hoisted)
  let state = {
    active: false,
    sessionName: "",
    countedBy: "",
    startedAt: "",
    pausedAt: "",
    completedAt: "",
    entries: [], // array of entry
    draft: { step: "idle", location: "", part: "", partKey: "", thick: null, sheetThickSource: "", type: "", desc: "", stackHeight: null, paper: null },
    pendingConfirm: null, // { kind, text }
    sigDataUrl: "",
    listening: false,
    lang: "en" // "en" | "es"
  };

  const PAPER_THICK = 0.004;

  const normPart = (v) => String(v || "").toUpperCase().replace(/[^A-Z0-9]/g, "").trim();

  const setWarn = (msg) => {
    if (!E.miWarn) return;
    if (!msg) { E.miWarn.style.display = "none"; E.miWarn.textContent = ""; return; }
    E.miWarn.style.display = "inline-flex";
    E.miWarn.textContent = msg;
  };
  const setOk = (msg) => {
    if (!E.miOk) return;
    if (!msg) { E.miOk.style.display = "none"; E.miOk.textContent = ""; return; }
    E.miOk.style.display = "inline-flex";
    E.miOk.textContent = msg;
  };

  const chip = (kind, text) => {
    if (!E.miStatusChip) return;
    E.miStatusChip.classList.remove("good", "bad", "warn");
    if (kind) E.miStatusChip.classList.add(kind);
    E.miStatusChip.textContent = text;
  };

  const nowStamp = () => new Date().toISOString();

  const safeSessionName = (s) => (s || "").replace(/[^\w \-#]/g, "").trim().slice(0, 80);

  let dbMap = null; // partKey -> record
  const loadDb = async () => {
    if (dbMap) return dbMap;
    if (typeof XLSX === "undefined") {
      throw new Error("XLSX library not loaded. Connect to internet and reload.");
    }
    // Decode base64 to ArrayBuffer
    const bin = atob(METAL_INV_XLSX_B64);
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    const wb = XLSX.read(bytes, { type: "array" });
    const sheetName = wb.SheetNames[0];
    const ws = wb.Sheets[sheetName];
    const rows = XLSX.utils.sheet_to_json(ws, { header: 1, raw: true, defval: "" });

    // Find header row containing PART# and THICK
    let headerRowIdx = -1;
    let partCol = -1, thickCol = -1, typeCol = -1, descCol = -1;
    for (let r = 0; r < Math.min(rows.length, 30); r++) {
      const row = (rows[r] || []).map(x => String(x || "").trim().toUpperCase());
      const p = row.indexOf("PART#");
      const t = row.indexOf("THICK");
      if (p >= 0 && t >= 0) {
        headerRowIdx = r;
        partCol = p;
        thickCol = t;
        typeCol = row.indexOf("TYPE");
        descCol = row.indexOf("DESCRIPTION");
        break;
      }
    }
    if (headerRowIdx < 0) throw new Error("Could not find PART#/THICK header row in Metal_Inventory.xlsx.");

    const map = {};
    for (let r = headerRowIdx + 1; r < rows.length; r++) {
      const row = rows[r] || [];
      const part = String(row[partCol] || "").trim();
      if (!part) continue;
      const key = normPart(part);
      if (!key) continue;

      const thickRaw = row[thickCol];
      const thick = parseFloat(String(thickRaw || "").trim());
      const rec = {
        part,
        partKey: key,
        thick: Number.isFinite(thick) ? thick : null,
        type: typeCol >= 0 ? String(row[typeCol] || "").trim() : "",
        desc: descCol >= 0 ? String(row[descCol] || "").trim() : ""
      };
      map[key] = rec;
    }

    dbMap = map;
    return dbMap;
  };

  const parseStackPhrase = (txt) => {
    const raw = String(txt || "").trim().toLowerCase();
    // Expect: "<number> paper" or "<number> no paper"
    const numMatch = raw.match(/(\d+(\.\d+))/);
    const h = numMatch ? parseFloat(numMatch[1]) : NaN;
    const hasNo = /\bno\s+paper\b/.test(raw);
    const hasPaper = /\bpaper\b/.test(raw) && !hasNo;
    const paper = hasPaper ? true : hasNo ? false : null;
    return { height: h, paper };
  };

  const normLocation = (txt) => {
    let s = String(txt || "").trim().toUpperCase();
    // Phonetic replacements
    // 1. Remove ignore words
    s = s.replace(/\b(RACK|LOCATION|THE)\b/g, "");

    // 2. Phonetic replacements 
    s = s.replace(/\bALPHA\b/g, "A");
    s = s.replace(/\bBRAVO\b|\bBETA\b/g, "B");
    s = s.replace(/\bCHARLIE\b/g, "C");
    s = s.replace(/\bDELTA\b/g, "D");
    s = s.replace(/\bECHO\b/g, "E");
    s = s.replace(/\bFOXTROT\b/g, "F");
    s = s.replace(/\bGOLF\b/g, "G");
    s = s.replace(/\bHOTEL\b/g, "H");

    // 3. Word-numbers to digits
    s = s.replace(/\bONE\b/g, "1");
    s = s.replace(/\bTWO\b/g, "2");
    s = s.replace(/\bTHREE\b/g, "3");
    s = s.replace(/\bFOUR\b/g, "4");
    s = s.replace(/\bFIVE\b/g, "5");
    s = s.replace(/\bSIX\b/g, "6");
    s = s.replace(/\bSEVEN\b/g, "7");
    s = s.replace(/\bEIGHT\b/g, "8");
    s = s.replace(/\bNINE\b/g, "9");
    s = s.replace(/\bZERO\b/g, "0");

    // 4. Remove all whitespace to mash it together: "A 1" -> "A1"
    s = s.replace(/\s+/g, "");

    return s;
  };

  const calcQty = ({ stackHeight, sheetThick, paper }) => {
    const p = paper ? PAPER_THICK : 0;
    const effective = (sheetThick || 0) + p;
    if (!(stackHeight > 0) || !(effective > 0)) return { qty: null, effective: null, remainder: null };
    const qty = Math.floor(stackHeight / effective);
    const remainder = stackHeight - (qty * effective);
    return { qty, effective, remainder };
  };

  // Simple chat renderer
  const chat = {
    clear() { if (E.miChat) E.miChat.innerHTML = ""; },
    pushSys(text) {
      if (!E.miChat) return;
      const d = document.createElement("div");
      d.className = "miBubble sys";
      d.innerHTML = `<div>${U.escape(text)}</div><small>App</small>`;
      E.miChat.appendChild(d);
      E.miChat.scrollTop = E.miChat.scrollHeight;
    },
    pushUser(text) {
      if (!E.miChat) return;
      const d = document.createElement("div");
      d.className = "miBubble user";
      d.innerHTML = `<div>${U.escape(text)}</div><small>You</small>`;
      E.miChat.appendChild(d);
      E.miChat.scrollTop = E.miChat.scrollHeight;
    }
  };

  /* Better Voice Selection Helper */
  let _cachedVoice = null;
  const getVoice = (lang = "en") => {
    // We intentionally don't cache aggressively if language might switch
    const voices = window.speechSynthesis.getVoices();
    if (!voices.length) return null;

    if (lang === "es") {
      return voices.find(v => v.name.includes("Google español")) ||
        voices.find(v => v.name.includes("Sabina")) || // Microsoft Sabina
        voices.find(v => v.name.includes("Paulina")) || // Microsoft Paulina
        voices.find(v => v.name.includes("Mexico")) ||
        voices.find(v => v.name.includes("Spain")) ||
        voices.find(v => v.lang.startsWith("es")) ||
        voices[0];
    } else {
      return voices.find(v => v.name.includes("Google US English")) ||
        voices.find(v => v.name.includes("Zira")) ||
        voices.find(v => v.name.includes("Natural")) ||
        voices.find(v => v.name.includes("Female")) ||
        voices.find(v => v.lang === "en-US") ||
        voices[0];
    }
  };

  // Ensure voices are loaded (Chrome quirk)
  if (typeof window !== "undefined" && "speechSynthesis" in window) {
    window.speechSynthesis.onvoiceschanged = () => { _cachedVoice = null; getVoice(); };
  }

  /* TTS: Browser SpeechSynthesis Only (Backend Removed) */
  const speakAsync = async (text) => {
    // Fallback: Browser SpeechSynthesis
    return new Promise((resolve) => {
      try {
        if (!("speechSynthesis" in window)) { resolve(); return; }
        window.speechSynthesis.cancel();
        const u = new SpeechSynthesisUtterance(String(text || ""));
        const useLang = state.lang || "en";
        const v = getVoice(useLang);
        if (v) u.voice = v;
        u.lang = useLang === "es" ? "es-ES" : "en-US";
        u.rate = 0.95;
        u.pitch = 1.0;
        u.volume = 1.0;
        u.onend = () => resolve();
        u.onerror = (e) => resolve();
        window.speechSynthesis.speak(u);
        // Safety timeout
        setTimeout(resolve, (text.length * 100) + 1000);
      } catch (e) { resolve(); }
    });
  };

  // Backwards compat shim if needed, or just redirect
  const speak = (text) => speakAsync(text);

  const Speech = (() => {
    const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
    const supported = !!SR;

    const listenOnce = ({ promptText, lang = "en-US", expectYesNo = false, timeoutMs = 15000 } = {}) => new Promise((resolve) => {
      if (!supported) {
        resolve({ ok: false, text: "", error: "SpeechRecognition not supported" });
        return;
      }
      const rec = new SR();
      rec.lang = lang;
      rec.interimResults = false;
      rec.maxAlternatives = 1;
      let done = false;

      const finish = (res) => {
        if (done) return;
        done = true;
        try { rec.stop(); } catch { }
        resolve(res);
      };

      // Longer timeout for industrial env
      const timer = setTimeout(() => finish({ ok: false, text: "", error: "timeout" }), timeoutMs);

      rec.onresult = (e) => {
        clearTimeout(timer);
        const t = e && e.results && e.results[0] && e.results[0][0] && e.results[0][0].transcript
          ? String(e.results[0][0].transcript).trim()
          : "";
        if (expectYesNo) {
          const low = t.toLowerCase();
          // Broaden yes/no matching - significantly more natural options
          const yes = /\b(yes|yeah|yep|yup|correct|confirm|affirmative|sure|ok|okay|right|good|save|store|si|sí|claro|bueno|es correcto|está bien|guardar)\b/i.test(low);
          const no = /\b(no|nope|negative|retry|incorrect|nah|wrong|cancel|wait|stop|back|mal|error|repetir|cancelar)\b/i.test(low);

          if (yes) finish({ ok: true, text: "yes", raw: t });
          else if (no) finish({ ok: true, text: "no", raw: t });
          else finish({ ok: false, text: t, raw: t, error: "not_yes_no" });
          return;
        }
        finish({ ok: !!t, text: t, raw: t, error: t ? "" : "empty" });
      };
      rec.onerror = (e) => {
        clearTimeout(timer);
        if (e.error === "no-speech") {
          // benign, just timeout
          finish({ ok: false, text: "", error: "timeout" });
          return;
        }
        console.warn("Speech error:", e.error);
        finish({ ok: false, text: "", error: e.error || "error" });
      };
      rec.onend = () => { if (!done) finish({ ok: false, text: "", error: "end_gap" }); };

      try {
        if (promptText) chat.pushSys(promptText);
        rec.start();
      } catch (e) {
        clearTimeout(timer);
        console.error("Speech start failed:", e);
        finish({ ok: false, text: "", error: "start_failed: " + (e.message || String(e)) });
      }
    });

    return { supported, listenOnce };
  })();

  // Signature pad (canvas)
  const Sig = (() => {
    let drawing = false;
    let hasInk = false;
    let ctx = null;

    const resizeForHiDpi = () => {
      const c = E.miSigCanvas;
      if (!c) return;
      const ratio = Math.max(1, window.devicePixelRatio || 1);
      const rect = c.getBoundingClientRect();
      // Keep attribute size for layout; scale internal for crisp lines
      c.width = Math.round(rect.width * ratio);
      c.height = Math.round(rect.height * ratio);
      ctx = c.getContext("2d");
      ctx.scale(ratio, ratio);
      ctx.lineWidth = 2.2;
      ctx.lineCap = "round";
      ctx.lineJoin = "round";
      ctx.strokeStyle = "#111";
      // Do not auto-clear here (avoid losing signature). Caller will re-draw from saved if needed.
    };

    const clear = () => {
      const c = E.miSigCanvas;
      if (!c) return;
      const ctx2d = c.getContext("2d");
      ctx2d.clearRect(0, 0, c.width, c.height);
      hasInk = false;
    };

    const toDataUrl = () => {
      const c = E.miSigCanvas;
      if (!c) return "";
      return hasInk ? c.toDataURL("image/png") : "";
    };

    const drawLine = (x0, y0, x1, y1) => {
      const c = E.miSigCanvas;
      if (!c) return;
      const ctx2d = c.getContext("2d");
      ctx2d.beginPath();
      ctx2d.moveTo(x0, y0);
      ctx2d.lineTo(x1, y1);
      ctx2d.stroke();
    };

    const bind = () => {
      const c = E.miSigCanvas;
      if (!c) return;
      // Initialize style
      const ctx2d = c.getContext("2d");
      ctx2d.lineWidth = 2.2;
      ctx2d.lineCap = "round";
      ctx2d.lineJoin = "round";
      ctx2d.strokeStyle = "#111";

      let last = null;
      const pos = (e) => {
        const rect = c.getBoundingClientRect();
        const x = (e.clientX - rect.left);
        const y = (e.clientY - rect.top);
        return { x, y };
      };

      c.addEventListener("pointerdown", (e) => {
        drawing = true;
        c.setPointerCapture(e.pointerId);
        last = pos(e);
      });
      c.addEventListener("pointermove", (e) => {
        if (!drawing) return;
        const p = pos(e);
        if (last) {
          drawLine(last.x, last.y, p.x, p.y);
          hasInk = true;
        }
        last = p;
      });
      const end = (e) => {
        drawing = false;
        last = null;
        try { c.releasePointerCapture(e.pointerId); } catch { }
      };
      c.addEventListener("pointerup", end);
      c.addEventListener("pointercancel", end);

      E.miSigClear.addEventListener("click", () => {
        clear();
        persist();
      });

      // HiDPI resize on first load and when layout changes
      // (keep it simple: do one-time setup; signature canvas has fixed height)
      // We avoid automatic resize afterwards to prevent wiping ink.
    };

    return { bind, clear, toDataUrl, hasInk: () => hasInk, setHasInk: (v) => { hasInk = !!v; } };
  })();

  // Session state
  // Session state (Moved to top of IIFE)
  // let state = { ... };

  const persist = () => {
    try { localStorage.setItem(LS_ACTIVE, JSON.stringify(state)); } catch (e) { }
  };

  const loadPersisted = () => {
    const raw = localStorage.getItem(LS_ACTIVE);
    const st = U.safeJSON(raw, null);
    if (!st) return;
    state = Object.assign(state, st);
    // ensure arrays
    state.entries = Array.isArray(state.entries) ? state.entries : [];
    state.draft = Object.assign({
      step: "idle",
      location: "",
      part: "",
      partKey: "",
      thick: null,
      sheetThickSource: "",
      type: "",
      desc: "",
      stackHeight: null,
      paper: null
    }, state.draft || {});
    state.listening = false;
  };

  const resetDraft = () => {
    state.draft = { step: "location", location: "", part: "", partKey: "", thick: null, sheetThickSource: "", type: "", desc: "", stackHeight: null, paper: null };
    state.pendingConfirm = null;
    setWarn("");
    persist();
  };

  const setButtons = (mode) => {
    // mode: "idle" | "awaitConfirm"
    const confirm = mode === "awaitConfirm";
    const busy = !!state.listening;
    if (E.miYes) E.miYes.disabled = !confirm || busy;
    if (E.miNo) E.miNo.disabled = !confirm || busy;
    if (E.miRecord) E.miRecord.disabled = confirm || !state.active || busy;
    if (E.miPause) E.miPause.disabled = !state.active || busy;
    if (E.miManual) E.miManual.disabled = busy;
    if (E.miEditDraft) E.miEditDraft.disabled = !state.active || busy;
    // Allow export if we have entries, even if paused
    if (E.miComplete) E.miComplete.disabled = !(state.entries.length > 0);
  };

  const setListening = (v) => {
    state.listening = !!v;
    setButtons(state.pendingConfirm ? "awaitConfirm" : "idle");
  };

  const listenOnce = async (opts) => {
    setListening(true);
    try {
      return await Speech.listenOnce(opts);
    } finally {
      setListening(false);
    }
  };

  const renderEntries = () => {
    if (!E.miEntries) return;
    const ents = state.entries || [];
    if (E.miCountChip) E.miCountChip.textContent = String(ents.length);
    if (ents.length === 0) {
      E.miEntries.innerHTML = `<div class="hint">No entries yet.</div>`;
      return;
    }
    E.miEntries.innerHTML = ents.map((e, idx) => {
      const paperText = e.paper ? "Paper" : "No Paper";
      return `
        <div class="miEntry">
          <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:12px; border-bottom:1px solid rgba(255,255,255,0.1); padding-bottom:8px;">
            <div style="font-family:'JetBrains Mono'; font-size:1.1rem; color:var(--neon-cyan); font-weight:800;">${U.escape(e.location || "LOC")}</div>
            <div style="display:flex; gap:6px; align-items:center;">
              <button type="button" data-mi-edit="${idx}" style="padding:6px 12px; min-width:auto; font-size:0.7rem; border:1px solid rgba(0,242,234,0.5); background: rgba(0,242,234,0.08); color:#7ffdf7;">EDIT</button>
              <button type="button" data-mi-del="${idx}" class="danger" style="padding:6px 12px; min-width:auto; font-size:0.7rem;">DEL</button>
            </div>
          </div>
          
          <div class="miEntryDetails">
            <div class="data-point">
              <span>Part #</span>
              <strong style="color:#fff; font-size:1rem;">${U.escape(e.part || "")}</strong>
            </div>
            <div class="data-point">
              <span>Qty</span>
              <strong style="color:var(--neon-green); font-size:1.1rem;">${U.escape(String(e.qty ?? ""))}</strong>
            </div>
            <div class="data-point">
              <span>Stack</span>
              <strong>${paperText}</strong>
            </div>
          </div>
          
          <div class="miEntryDetails" style="margin-top:8px;">
             <div class="data-point">
              <span>Height</span>
              <strong>${U.escape(String(e.stackHeight || ""))}″</strong>
            </div>
             <div class="data-point">
              <span>Thick</span>
              <strong>${U.escape(String(e.sheetThick || ""))}″</strong>
            </div>
             <div class="data-point">
              <span>Timestamp</span>
              <span style="font-size:0.65rem; opacity:0.7">${(e.createdAt || "").split("T")[1].slice(0, 5)}</span>
            </div>
          </div>
        </div>
      `;
    }).join("");

    E.miEntries.querySelectorAll("button[data-mi-del]").forEach(btn => {
      btn.addEventListener("click", () => {
        const i = parseInt(btn.getAttribute("data-mi-del"), 10);
        if (!Number.isFinite(i)) return;
        state.entries.splice(i, 1);
        persist();
        renderEntries();
        setButtons(state.pendingConfirm ? "awaitConfirm" : "idle");
      });
    });

    E.miEntries.querySelectorAll("button[data-mi-edit]").forEach(btn => {
      btn.addEventListener("click", () => {
        const i = parseInt(btn.getAttribute("data-mi-edit"), 10);
        if (!Number.isFinite(i)) return;
        manualEditEntry(i);
      });
    });
  };

  const updateHeader = () => {
    if (E.miCountedBy) state.countedBy = E.miCountedBy.value || "";
    if (E.miSessionName) state.sessionName = safeSessionName(E.miSessionName.value || "");
    persist();
  };

  const startOrResume = () => {
    setOk("");
    setWarn("");
    if (!state.sessionName) {
      const d = new Date();
      const mm = String(d.getMonth() + 1).padStart(2, "0");
      const dd = String(d.getDate()).padStart(2, "0");
      const yy = d.getFullYear();
      const hh = d.getHours() % 12 || 12;
      const min = String(d.getMinutes()).padStart(2, "0");
      const ap = d.getHours() >= 12 ? "PM" : "AM";
      state.sessionName = `Metal Inventory - ${mm}-${dd}-${yy} ${hh}:${min} ${ap}`;
    }
    state.active = true;
    state.startedAt = state.startedAt || nowStamp();
    state.pausedAt = "";
    if (E.miSessionName) E.miSessionName.value = state.sessionName;
    chip("warn", "Session Active");
    resetDraft();
    chat.clear();
    chat.pushSys("Session active. Press Record Next to begin.");
    renderEntries();
    setButtons("idle");
    persist();
  };

  const pause = () => {
    state.active = false;
    state.pausedAt = nowStamp();
    chip("bad", "Session Paused");
    setButtons("idle");
    persist();
  };

  const newSession = () => {
    state = {
      active: false, sessionName: "", countedBy: "", startedAt: "", pausedAt: "", completedAt: "",
      entries: [],
      draft: { step: "idle", location: "", part: "", partKey: "", thick: null, sheetThickSource: "", type: "", desc: "", stackHeight: null, paper: null },
      pendingConfirm: null,
      sigDataUrl: "",
      listening: false
    };
    try { localStorage.removeItem(LS_ACTIVE); } catch (e) { }
    chat.clear();
    chip("", "No Active Session");
    renderEntries();
    setButtons("idle");
    setWarn("");
    setOk("");
    if (E.miCountedBy) E.miCountedBy.value = "";
    if (E.miSessionName) E.miSessionName.value = "";
    Sig.clear();
  };

  const confirmPrompt = async (opts) => {
    const cfg = typeof opts === "string" ? { text: opts } : (opts || {});
    const text = String(cfg.text || "");
    const lang = cfg.lang || cfg.langCode || "en-US";
    const correctText = cfg.correctText || "Correct";
    const timeoutMs = cfg.timeoutMs || 20000;
    const voiceFailText = cfg.voiceFailText || "Voice unclear. Use buttons.";

    state.pendingConfirm = { text };
    persist();
    setButtons("awaitConfirm");
    chat.pushSys(text);

    await speakAsync(text);
    if (correctText) await speakAsync(correctText);

    await new Promise(r => setTimeout(r, 100));

    const res = await listenOnce({ expectYesNo: true, timeoutMs, lang });
    if (res.ok && (res.text === "yes" || res.text === "no")) {
      state.pendingConfirm = null;
      persist();
      setButtons("idle");
      return { answer: res.text, raw: res.raw || "", via: "voice" };
    }

    if (voiceFailText) chat.pushSys(voiceFailText);

    return new Promise((resolve) => {
      let resolved = false;
      const finish = (val) => {
        if (resolved) return;
        resolved = true;
        cleanup();
        state.pendingConfirm = null;
        persist();
        setButtons("idle");
        resolve({ answer: val, raw: "", via: "button" });
      };

      const yes = () => finish("yes");
      const no = () => finish("no");

      const cleanup = () => {
        E.miYes.removeEventListener("click", yes);
        E.miNo.removeEventListener("click", no);
      };

      E.miYes.addEventListener("click", yes);
      E.miNo.addEventListener("click", no);
    });
  };

  /* SINGLE-SLOT STRICT EXTRACTION */
  /* BOLDER MULTI-SLOT EXTRACTION */
  const extractSlots = (text, currentMode) => {
    const raw = String(text || "").trim();
    const isEs = state.lang === "es";
    const res = {};

    // Helper regexes
    const RE = {
      locKw: isEs ? /(?:ubic\S*|loca\S*|estante|anaquel|fila)/i : /(?:loc\S*|rack|bin|shelf)/i,
      partKw: isEs ? /(?:parte|art\S*|n[u\u00FA]mero|pieza)/i : /(?:part|item|number|num|p#)/i,
      thickKw: isEs ? /(?:espesor|grosor|calibre)/i : /(?:thick\S*|gauge)/i,
      sheetKw: isEs ? /(?:espesor\s+de\s+hoja|hoja\s+espesor|calibre\s+de\s+hoja)/i : /(?:sheet\s*thick\S*|sheet\s*gauge|per\s*sheet)/i,
      stackKw: isEs ? /(?:pila|altura|stack|alto)/i : /(?:stack|height|pile|hight)/i,
      paperKw: isEs ? /(?:papel|sin papel)/i : /(?:paper|no paper)/i,
      changeKw: isEs ? /(?:cambia|corrige|modifica|no\s+es|error)/i : /(?:change|correct|modify|not|fix|wrong)/i,
      stopWords: /^(LOC|PART|ITEM|NUM|THICK|PAPER|NO|STOP|EXIT|PARTE|PIEZA|ESPESOR|GROSOR|PAPEL|ALTO|PARA|SALIR|SI|S\u00CD|YES)$/i
    };

    // 1. EXPLICIT EXTRACTIONS (Keywords)

    // Location
    const locMatch = raw.match(new RegExp(`${RE.locKw.source}\\s+([a-zA-Z0-9\\-\\.]+)`, "i"));
    if (locMatch) res.location = normLocation(locMatch[1]);

    // Part
    const partMatch = raw.match(new RegExp(`${RE.partKw.source}\\s+([a-zA-Z0-9\\-\\.]+)`, "i"));
    if (partMatch) {
      res.part = String(partMatch[1]).trim().toUpperCase();
      res.partKey = normPart(res.part);
    }

    // Thickness (stack height unless explicitly sheet thickness mode)
    const thickMatch = raw.match(new RegExp(`${RE.thickKw.source}\\s*(\\d+(\\.\\d+))`, "i"));
    if (thickMatch) {
      const t = parseFloat(thickMatch[1]);
      if (t > 0 && t <= 8.5) {
        if (currentMode === "sheet") res.thick = t;
        else res.stackHeight = t;
      }
    }

    // Sheet thickness (explicit)
    const sheetMatch = raw.match(new RegExp(`${RE.sheetKw.source}\\s*(\\d+(\\.\\d+))`, "i"));
    if (sheetMatch) {
      const t = parseFloat(sheetMatch[1]);
      if (t > 0 && t <= 8.5) res.thick = t;
    }

    // Stack/Paper
    const stackInfo = parseStackPhrase(raw);
    if (stackInfo.height > 0 && stackInfo.height <= 8.5) res.stackHeight = stackInfo.height;
    if (stackInfo.paper !== null) res.paper = stackInfo.paper;

    if (currentMode === "paper" || RE.paperKw.test(raw)) {
      const low = raw.toLowerCase();
      if (/\b(no|nope|nah|sin)\b/.test(low)) res.paper = false;
      if (/\b(yes|yeah|yep|yup|paper|si|sÃ­)\b/.test(low)) res.paper = true;
    }

    // 2. IMPLICIT EXTRACTION (Based on currentMode or Contextual Clues)
    const tokens = raw.split(/\s+/).filter(t => !RE.stopWords.test(t.toUpperCase()));
    const firstToken = tokens[0] ? tokens[0] : "";

    if (currentMode === "location" && !res.location && firstToken) {
      res.location = normLocation(firstToken);
    } else if (currentMode === "part" && !res.part && firstToken) {
      res.part = firstToken.toUpperCase();
      res.partKey = normPart(res.part);
    } else if (currentMode === "sheet" && !res.thick) {
      const numMatch = raw.match(/(\d+(\.\d+))/);
      if (numMatch) {
        const t = parseFloat(numMatch[1]);
        if (t > 0 && t <= 8.5) res.thick = t;
      }
    } else if ((currentMode === "stack" || currentMode === "thickness") && !res.stackHeight) {
      const nums = raw.match(/(\d+(\.\d+))/g);
      if (nums) {
        const h = nums.find(n => {
          const val = parseFloat(n);
          return val > 0.05 && val <= 8.5;
        });
        if (h) res.stackHeight = parseFloat(h);
      }
    }

    // Capture "correction" intent
    if (RE.changeKw.test(raw)) res._correction = true;
    return res;
  };

  const doStep = async () => {
    if (!state.active) {
      setWarn(state.lang === "es" ? "Sesion pausada." : "Session paused.");
      return;
    }
    setWarn("");
    setOk("");
    updateHeader();

    await loadDb().catch((e) => {
      setWarn("DB Error: " + e.message);
      throw e;
    });

    const d = state.draft || {};
    const isEs = state.lang === "es";
    const langCode = isEs ? "es-ES" : "en-US";
    const map = dbMap || {};

    const P = {
      readyLoc: isEs ? "Ubicacion?" : "Location?",
      paused: isEs ? "Sesion pausada." : "Session paused.",
      captured: isEs ? "[C]" : "[C]",
      noInput: isEs ? "Reintentar." : "Retrying.",
      partNum: isEs ? "Numero de parte?" : "Part number?",
      thickness: isEs ? "Espesor?" : "Thickness?",
      paper: isEs ? "Papel?" : "Paper?",
      sheetThick: isEs ? "Espesor de la hoja?" : "Sheet thickness?",
      calcErr: isEs ? "Error de calculo." : "Calculation error.",
      correct: isEs ? "Correcto?" : "Correct?",
      saved: isEs ? "Guardado." : "Saved.",
      corrected: isEs ? "Corregido." : "Corrected.",
      whatWrong: isEs ? "Que estuvo mal? Ubicacion, parte, espesor o papel." : "What was wrong? Say location, part, thickness, or paper.",
      voiceUnclear: isEs ? "Voz no clara. Use botones." : "Voice unclear. Use buttons.",
      needField: isEs ? "Diga el campo o el valor correcto." : "Say the field or the corrected value.",
      readback: (draft, qty) => {
        const paperText = draft.paper ? (isEs ? "con papel" : "paper") : (isEs ? "sin papel" : "no paper");
        const thickText = Number.isFinite(draft.stackHeight) ? draft.stackHeight : "";
        const base = isEs
          ? `Ubicacion ${draft.location}, parte ${draft.part}, espesor ${thickText} pulgadas, ${paperText}.`
          : `Location ${draft.location}, part ${draft.part}, thickness ${thickText} inches, ${paperText}.`;
        const qtyText = isEs ? `Cantidad ${qty}.` : `Calculated ${qty} pieces.`;
        const sheetText = draft.sheetThickSource === "manual"
          ? (isEs ? `Espesor de hoja ${draft.thick} pulgadas.` : `Sheet thickness ${draft.thick} inches.`)
          : "";
        return `${base} ${sheetText} ${qtyText}`.trim();
      }
    };

    const isStop = (text) => /\b(stop|cancel|exit|finish|done|pause|alto|salir|terminar)\b/i.test(String(text || ""));
    const paperFromText = (text) => {
      const low = String(text || "").toLowerCase();
      if (/\b(no|nope|nah|sin)\b/.test(low)) return false;
      if (/\b(yes|yeah|yep|yup|paper|si)\b/.test(low)) return true;
      return null;
    };

    const announceDraft = (slots) => {
      const parts = [];
      if (slots.location) parts.push(isEs ? `Ubic:${slots.location}` : `Loc:${slots.location}`);
      if (slots.part) parts.push(isEs ? `Parte:${slots.part}` : `Part:${slots.part}`);
      if (slots.stackHeight) parts.push(isEs ? `Esp:${slots.stackHeight}"` : `Thk:${slots.stackHeight}"`);
      if (slots.thick) parts.push(isEs ? `Hoja:${slots.thick}"` : `Sheet:${slots.thick}"`);
      if (slots.paper !== undefined) parts.push(slots.paper ? (isEs ? "Papel" : "Paper") : (isEs ? "SinPapel" : "NoPaper"));
      if (parts.length > 0) {
        chat.pushSys(`${P.captured} ${parts.join(", ")}`);
      }
    };

    const applyPartRecord = (partKey) => {
      if (!partKey) return;
      const rec = map[partKey];
      if (!rec) {
        d.type = "";
        d.desc = "";
        return;
      }
      d.type = rec.type || "";
      d.desc = rec.desc || "";
      if (rec.thick && d.sheetThickSource !== "manual") {
        d.thick = rec.thick;
        d.sheetThickSource = "db";
      }
    };

    const applySlotsToDraft = (slots) => {
      if (!slots) return false;
      let changed = false;
      let partChanged = false;

      if (slots.location) {
        d.location = slots.location;
        changed = true;
      }
      if (slots.part) {
        d.part = slots.part;
        d.partKey = slots.partKey || normPart(slots.part);
        partChanged = true;
        changed = true;
      } else if (slots.partKey && !d.partKey) {
        d.partKey = slots.partKey;
        d.part = d.part || slots.partKey;
        partChanged = true;
        changed = true;
      }

      if (partChanged) {
        d.type = "";
        d.desc = "";
        d.thick = null;
        d.sheetThickSource = "";
      }

      if (slots.thick) {
        d.thick = slots.thick;
        d.sheetThickSource = "manual";
        changed = true;
      }
      if (slots.stackHeight) {
        d.stackHeight = slots.stackHeight;
        changed = true;
      }
      if (slots.paper !== undefined && slots.paper !== null) {
        d.paper = slots.paper;
        changed = true;
      }

      if (d.partKey) applyPartRecord(d.partKey);
      return changed;
    };

    const listenFor = async (promptText, { timeoutMs = 30000 } = {}) => {
      if (promptText) {
        chat.pushSys(promptText);
        await speakAsync(promptText);
      }
      const r = await listenOnce({ timeoutMs, lang: langCode });
      if (!r.ok) {
        setWarn(P.noInput);
        return null;
      }
      if (isStop(r.text)) {
        chat.pushSys(P.paused);
        await speakAsync(P.paused);
        pause();
        return null;
      }
      chat.pushUser(r.text);
      return r;
    };

    const askLocation = async () => {
      const r = await listenFor(P.readyLoc, { timeoutMs: 30000 });
      if (!r) return false;
      const slots = extractSlots(r.text, "location");
      announceDraft(slots);
      if (!slots.location) {
        setWarn(P.noInput);
        return false;
      }
      applySlotsToDraft(slots);
      persist();
      return true;
    };

    const askPart = async () => {
      const prompt = isEs ? `(Ubic: ${d.location}) ${P.partNum}` : `(Loc: ${d.location}) ${P.partNum}`;
      const r = await listenFor(prompt, { timeoutMs: 30000 });
      if (!r) return false;
      const slots = extractSlots(r.text, "part");
      announceDraft(slots);
      if (!slots.part && !slots.partKey) {
        setWarn(P.noInput);
        return false;
      }
      applySlotsToDraft(slots);
      persist();
      return true;
    };

    const askSheetThickness = async () => {
      const r = await listenFor(P.sheetThick, { timeoutMs: 20000 });
      if (!r) return false;
      const slots = extractSlots(r.text, "sheet");
      if (slots.thick) {
        d.thick = slots.thick;
        d.sheetThickSource = "manual";
        announceDraft({ thick: d.thick });
        persist();
        return true;
      }
      const numMatch = r.text.match(/(\d+(\.\d+)?)/);
      if (numMatch) {
        const t = parseFloat(numMatch[1]);
        if (t > 0 && t <= 8.5) {
          d.thick = t;
          d.sheetThickSource = "manual";
          announceDraft({ thick: d.thick });
          persist();
          return true;
        }
      }
      setWarn(P.noInput);
      return false;
    };

    const askThickness = async () => {
      const r = await listenFor(P.thickness, { timeoutMs: 30000 });
      if (!r) return false;
      const slots = extractSlots(r.text, "stack");
      announceDraft(slots);
      if (slots.stackHeight) {
        d.stackHeight = slots.stackHeight;
        persist();
        return true;
      }
      const numMatch = r.text.match(/(\d+(\.\d+)?)/);
      if (numMatch) {
        const t = parseFloat(numMatch[1]);
        if (t > 0 && t <= 8.5) {
          d.stackHeight = t;
          persist();
          return true;
        }
      }
      setWarn(P.noInput);
      return false;
    };

    const askPaper = async () => {
      const r = await listenFor(P.paper, { timeoutMs: 20000 });
      if (!r) return false;
      const slots = extractSlots(r.text, "paper");
      if (slots.paper !== undefined && slots.paper !== null) d.paper = slots.paper;
      if (d.paper === null || d.paper === undefined) {
        const p = paperFromText(r.text);
        if (p !== null) d.paper = p;
      }
      if (d.paper === null || d.paper === undefined) {
        setWarn(P.noInput);
        return false;
      }
      announceDraft({ paper: d.paper });
      persist();
      return true;
    };

    const detectField = (text) => {
      const low = String(text || "").toLowerCase();
      if (/\b(sheet)\b/.test(low)) return "sheet";
      if (/\b(location|loc|rack|bin|shelf|ubic)\b/.test(low)) return "location";
      if (/\b(part|item|number|parte|pieza)\b/.test(low)) return "part";
      if (/\b(thick|thickness|height|stack|espesor|altura)\b/.test(low)) return "thickness";
      if (/\b(paper|papel)\b/.test(low)) return "paper";
      return "";
    };

    const repromptField = async (field) => {
      if (field === "location") d.location = "";
      if (field === "part") {
        d.part = "";
        d.partKey = "";
        d.type = "";
        d.desc = "";
        d.thick = null;
        d.sheetThickSource = "";
      }
      if (field === "thickness") d.stackHeight = null;
      if (field === "paper") d.paper = null;
      if (field === "sheet") {
        d.thick = null;
        d.sheetThickSource = "";
      }
      persist();

      if (field === "location") return askLocation().then(ok => ok && doStep());
      if (field === "part") return askPart().then(ok => ok && doStep());
      if (field === "thickness") return askThickness().then(ok => ok && doStep());
      if (field === "paper") return askPaper().then(ok => ok && doStep());
      if (field === "sheet") return askSheetThickness().then(ok => ok && doStep());
    };

    const handleCorrection = async (rawText) => {
      state.pendingConfirm = null;
      setButtons("idle");
      const raw = String(rawText || "").trim();
      if (raw && isStop(raw)) {
        chat.pushSys(P.paused);
        await speakAsync(P.paused);
        pause();
        return;
      }
      if (raw) {
        if (/\b(manual|edit)\b/i.test(raw)) {
          manualEditDraft();
          return;
        }
        const slots = extractSlots(raw, "any");
        if (applySlotsToDraft(slots)) {
          chat.pushSys(P.corrected);
          persist();
          return doStep();
        }
      }

      chat.pushSys(P.whatWrong);
      await speakAsync(P.whatWrong);
      const r = await listenOnce({ timeoutMs: 20000, lang: langCode });
      if (!r.ok) {
        chat.pushSys(P.voiceUnclear);
        return;
      }
      if (isStop(r.text)) {
        chat.pushSys(P.paused);
        await speakAsync(P.paused);
        pause();
        return;
      }
      chat.pushUser(r.text);

      if (/\b(manual|edit)\b/i.test(r.text)) {
        manualEditDraft();
        return;
      }

      const slots = extractSlots(r.text, "any");
      if (applySlotsToDraft(slots)) {
        chat.pushSys(P.corrected);
        persist();
        return doStep();
      }

      const field = detectField(r.text);
      if (field) {
        return repromptField(field);
      }

      chat.pushSys(P.needField);
    };

    // Flow
    if (!d.location) {
      if (await askLocation()) return doStep();
      return;
    }

    if (!d.part) {
      if (await askPart()) return doStep();
      return;
    }

    if (!d.stackHeight) {
      if (await askThickness()) return doStep();
      return;
    }

    if (d.paper === null) {
      if (await askPaper()) return doStep();
      return;
    }

    if (!d.thick) {
      if (await askSheetThickness()) return doStep();
      return;
    }

    const { qty, effective, remainder } = calcQty({ stackHeight: d.stackHeight, sheetThick: d.thick, paper: d.paper });
    if (qty === null) {
      setWarn(P.calcErr);
      await speakAsync(P.calcErr);
      return;
    }

    const readback = P.readback(d, qty);
    const confirmRes = await confirmPrompt({
      text: readback,
      lang: langCode,
      correctText: P.correct,
      timeoutMs: 25000,
      voiceFailText: P.voiceUnclear
    });

    if (!confirmRes || !confirmRes.answer) return;

    if (confirmRes.answer === "yes") {
      const entry = {
        createdAt: nowStamp(),
        location: d.location,
        part: d.part,
        partKey: d.partKey,
        materialType: d.type,
        description: d.desc,
        sheetThick: d.thick,
        stackHeight: d.stackHeight,
        paper: d.paper,
        paperThick: d.paper ? PAPER_THICK : 0,
        effectiveThick: effective,
        qty,
        remainder
      };
      state.entries = Array.isArray(state.entries) ? state.entries : [];
      state.entries.push(entry);

      resetDraft();
      persist();
      renderEntries();
      setButtons("idle");

      chat.pushSys(P.saved);
      return doStep();
    }

    await handleCorrection(confirmRes.raw || "");
  };




  const promptTextValue = (label, current) => {
    const v = window.prompt(`${label} (leave blank to keep):`, current || "");
    if (v === null) return null;
    const t = String(v || "").trim();
    if (!t) return undefined;
    return t;
  };

  const promptNumberValue = (label, current) => {
    const cur = Number.isFinite(current) ? String(current) : "";
    const v = window.prompt(`${label} (leave blank to keep):`, cur);
    if (v === null) return null;
    const t = String(v || "").trim();
    if (!t) return undefined;
    const num = parseFloat(t);
    return Number.isFinite(num) ? num : NaN;
  };

  const promptPaperValue = (current) => {
    const def = current === true ? "paper" : current === false ? "no paper" : "";
    const v = window.prompt('Paper between every sheet? Type "paper" or "no paper" (leave blank to keep):', def);
    if (v === null) return null;
    const t = String(v || "").trim().toLowerCase();
    if (!t) return undefined;
    if (t.includes("no")) return false;
    if (t.includes("paper") || t.includes("yes") || t === "y" || t === "si") return true;
    return NaN;
  };

  const manualEditDraft = async () => {
    if (!state.active) { setWarn("Start or Resume the session first."); return; }
    if (state.listening) { setWarn("Finish listening before manual edit."); return; }
    state.pendingConfirm = null;
    setButtons("idle");
    setWarn("");
    setOk("");
    updateHeader();
    await loadDb().catch(() => { });

    const d = state.draft || {};

    const loc = promptTextValue("Location", d.location);
    if (loc === null) return;
    if (loc !== undefined) d.location = normLocation(loc);

    const part = promptTextValue("Part #", d.part);
    if (part === null) return;
    if (part !== undefined) {
      d.part = part.toUpperCase();
      d.partKey = normPart(d.part);
      d.type = "";
      d.desc = "";
      d.thick = null;
      d.sheetThickSource = "";
      const rec = (dbMap || {})[d.partKey];
      if (rec) {
        d.type = rec.type || "";
        d.desc = rec.desc || "";
        if (rec.thick) {
          d.thick = rec.thick;
          d.sheetThickSource = "db";
        }
      }
    }

    const stack = promptNumberValue("Thickness (stack height) in inches", d.stackHeight);
    if (stack === null) return;
    if (Number.isNaN(stack)) { setWarn("Invalid thickness."); return; }
    if (stack !== undefined) d.stackHeight = stack;

    const paper = promptPaperValue(d.paper);
    if (paper === null) return;
    if (Number.isNaN(paper)) { setWarn("Invalid paper value."); return; }
    if (paper !== undefined) d.paper = paper;

    if (d.partKey && (!Number.isFinite(d.thick) || !(d.thick > 0))) {
      const sheet = promptNumberValue("Sheet thickness per sheet in inches", d.thick);
      if (sheet === null) return;
      if (Number.isNaN(sheet)) { setWarn("Invalid sheet thickness."); return; }
      if (sheet !== undefined) {
        d.thick = sheet;
        d.sheetThickSource = "manual";
      }
    }

    persist();
    chat.pushSys("Draft updated.");
    setButtons(state.pendingConfirm ? "awaitConfirm" : "idle");
    if (state.active) doStep();
  };

  const manualEditEntry = async (idx) => {
    const entry = (state.entries || [])[idx];
    if (!entry) return;
    setWarn("");
    setOk("");
    await loadDb().catch(() => { });

    const prev = U.clone(entry);

    const loc = promptTextValue("Location", entry.location);
    if (loc === null) return;
    if (loc !== undefined) entry.location = normLocation(loc);

    const part = promptTextValue("Part #", entry.part);
    if (part === null) return;
    if (part !== undefined) {
      entry.part = part.toUpperCase();
      entry.partKey = normPart(entry.part);
      entry.materialType = "";
      entry.description = "";
      entry.sheetThick = null;
      const rec = (dbMap || {})[entry.partKey];
      if (rec) {
        entry.materialType = rec.type || "";
        entry.description = rec.desc || "";
        if (rec.thick) entry.sheetThick = rec.thick;
      }
    }

    const stack = promptNumberValue("Thickness (stack height) in inches", entry.stackHeight);
    if (stack === null) return;
    if (Number.isNaN(stack)) { setWarn("Invalid thickness."); Object.assign(entry, prev); return; }
    if (stack !== undefined) entry.stackHeight = stack;

    const paper = promptPaperValue(entry.paper);
    if (paper === null) return;
    if (Number.isNaN(paper)) { setWarn("Invalid paper value."); Object.assign(entry, prev); return; }
    if (paper !== undefined) entry.paper = paper;

    if (!Number.isFinite(entry.sheetThick) || !(entry.sheetThick > 0)) {
      const sheet = promptNumberValue("Sheet thickness per sheet in inches", entry.sheetThick);
      if (sheet === null) return;
      if (Number.isNaN(sheet)) { setWarn("Invalid sheet thickness."); Object.assign(entry, prev); return; }
      if (sheet !== undefined) entry.sheetThick = sheet;
    }

    const { qty, effective, remainder } = calcQty({ stackHeight: entry.stackHeight, sheetThick: entry.sheetThick, paper: entry.paper });
    if (qty === null) { setWarn("Could not calculate qty."); Object.assign(entry, prev); return; }

    entry.paperThick = entry.paper ? PAPER_THICK : 0;
    entry.effectiveThick = effective;
    entry.qty = qty;
    entry.remainder = remainder;

    persist();
    renderEntries();
    setOk("Entry updated.");
  };
  const manualEntry = async () => {
    if (!state.active) { setWarn("Start or Resume the session first."); return; }
    setWarn("");
    setOk("");
    updateHeader();
    await loadDb().catch(() => { });

    const locRaw = (window.prompt("Location (example: Rack A1):", "") || "").trim();
    if (!locRaw) return;
    const loc = normLocation(locRaw);

    const partRaw = (window.prompt("Part #:", "") || "").trim();
    if (!partRaw) return;
    const part = partRaw.toUpperCase();

    const stack = parseFloat((window.prompt("Thickness (stack height) in inches (example: 7.25):", "") || "").trim());
    if (!(stack > 0)) return;

    const paperAns = (window.prompt('Paper between every sheet? Type "paper" or "no paper":', "paper") || "").trim().toLowerCase();
    const paper = paperAns.includes("no") ? false : true;

    const key = normPart(part);
    const map = dbMap || {};
    const rec = map[key] || null;
    let thick = rec && Number.isFinite(rec.thick) ? rec.thick : null;
    if (!(thick > 0)) {
      thick = parseFloat((window.prompt("Sheet thickness per sheet in inches (example: 0.063):", "") || "").trim());
      if (!(thick > 0)) return;
    }

    const { qty, effective, remainder } = calcQty({ stackHeight: stack, sheetThick: thick, paper });
    if (qty === null) { setWarn("Could not calculate qty."); return; }

    state.entries.push({
      createdAt: nowStamp(),
      location: loc,
      part,
      partKey: key,
      materialType: rec ? (rec.type || "") : "",
      description: rec ? (rec.desc || "") : "",
      sheetThick: thick,
      stackHeight: stack,
      paper,
      paperThick: paper ? PAPER_THICK : 0,
      effectiveThick: effective,
      qty,
      remainder
    });
    persist();
    renderEntries();
    chat.pushSys("Manual entry saved.");
    setButtons("idle");
  };
  const exportExcel = () => {
    setWarn("");
    setOk("");
    updateHeader();
    if (!(state.entries && state.entries.length > 0)) {
      setWarn("Add at least 1 entry before exporting.");
      return;
    }
    const sig = Sig.toDataUrl();
    if (!sig) {
      setWarn("Supervisor signature is required before exporting.");
      return;
    }

    if (typeof XLSX === "undefined") {
      setWarn("XLSX library not loaded. Connect to internet and reload.");
      return;
    }

    const header = [
      "SessionName", "CountedBy", "Location", "PartNumber", "MaterialType", "Description",
      "SheetThicknessIn", "StackHeightIn", "Paper", "PaperThicknessIn", "EffectiveThicknessIn",
      "CalculatedQty", "EntryTimestamp"
    ];

    const rows = (state.entries || []).map(e => ([
      state.sessionName || "",
      state.countedBy || "",
      e.location || "",
      e.part || "",
      e.materialType || "",
      e.description || "",
      e.sheetThick ?? "",
      e.stackHeight ?? "",
      e.paper ? "Y" : "N",
      e.paperThick ?? "",
      e.effectiveThick ?? "",
      e.qty ?? "",
      e.createdAt || ""
    ]));

    const wsCounts = XLSX.utils.aoa_to_sheet([header, ...rows]);

    const signRows = [
      ["SessionName", state.sessionName || ""],
      ["CountedBy", state.countedBy || ""],
      ["StartedAt", state.startedAt || ""],
      ["CompletedAt", nowStamp()],
      ["SupervisorSignatureDataUrl", sig]
    ];
    const wsSign = XLSX.utils.aoa_to_sheet(signRows);

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, wsCounts, "InventoryCounts");
    XLSX.utils.book_append_sheet(wb, wsSign, "SupervisorSignoff");

    const fileName = U.safeFileName([state.sessionName || "Metal_Inventory_Session"], "Metal_Inventory_Session") + ".xlsx";
    try {
      XLSX.writeFile(wb, fileName);
    } catch (e) {
      // Fallback: write to blob download
      const out = XLSX.write(wb, { bookType: "xlsx", type: "array" });
      const blob = new Blob([out], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" });
      const a = document.createElement("a");
      a.href = URL.createObjectURL(blob);
      a.download = fileName;
      document.body.appendChild(a);
      a.click();
      setTimeout(() => { try { URL.revokeObjectURL(a.href); a.remove(); } catch { } }, 500);
    }

    // mark completed and clear active session (keep UI)
    state.completedAt = nowStamp();
    state.active = false;
    chip("good", "Session Exported");
    setOk("Excel exported. Session marked complete.");
    persist();
    setButtons("idle");
  };

  const bind = () => {
    loadPersisted();

    // Default session name if empty
    if (E.miSessionName) E.miSessionName.value = state.sessionName || "";
    if (E.miCountedBy) E.miCountedBy.value = state.countedBy || "";

    // Init UI
    if (state.active) chip("warn", "Session Active");
    else if (state.entries && state.entries.length > 0) chip("bad", "Session Paused");
    else chip("", "No Active Session");

    renderEntries();
    setButtons(state.pendingConfirm ? "awaitConfirm" : "idle");

    // signature
    Sig.bind();

    E.miCountedBy.addEventListener("input", updateHeader);
    E.miSessionName.addEventListener("input", updateHeader);

    E.miStartResume.addEventListener("click", startOrResume);
    E.miPause.addEventListener("click", pause);
    E.miNewSession.addEventListener("click", () => {
      const ok = window.confirm("Start a NEW session and clear current data on this device");
      if (ok) newSession();
    });
    if (E.miLangToggle) {
      E.miLangToggle.onclick = () => {
        state.lang = state.lang === "es" ? "en" : "es";
        E.miLangToggle.textContent = state.lang.toUpperCase();
        console.log("Language switched to:", state.lang);
        persist();
      };
      // Init label
      E.miLangToggle.textContent = (state.lang || "en").toUpperCase();
    }
    E.miTestMic.addEventListener("click", async () => {
      if (!E.miTestStatus) return;
      E.miTestStatus.textContent = "Listening... speak now.";
      E.miTestStatus.style.color = "#0369a1";
      if (!Speech.supported) {
        E.miTestStatus.textContent = "Not Supported in this browser.";
        return;
      }
      const r = await Speech.listenOnce({ timeoutMs: 5000 });
      if (r.ok) {
        E.miTestStatus.textContent = `Success! Heard: "${r.text}"`;
        E.miTestStatus.style.color = "green";
      } else {
        E.miTestStatus.textContent = `Failed: ${r.error}`;
        E.miTestStatus.style.color = "red";
      }
    });

    E.miRecord.addEventListener("click", async () => {
      try {
        if (!Speech.supported) {
          setWarn("Voice-to-text not supported on this device/browser. Use Manual Entry.");
          return;
        }
        await doStep();
      } catch (e) { }
    });

    E.miManual.addEventListener("click", manualEntry);
    if (E.miEditDraft) E.miEditDraft.addEventListener("click", manualEditDraft);

    E.miComplete.addEventListener("click", exportExcel);

    // When opening tab, ensure chat hints
    if (E.pageMetalInventory) {
      // no-op; chat is session-based
    }
  };

  const init = () => {
    // no-op, handled by bind
  };

  return { init, bind };
})();
if (typeof window !== "undefined") window.MetalInventory = MetalInventory;



/* ---------- Bootstrap ---------- */
if (typeof window !== 'undefined' && window.MetalInventory) {
  window.addEventListener('load', () => {
    console.log('Metal Inventory Standalone Booting...');
    if (window.MetalInventory.bind) window.MetalInventory.bind();
  });
}
